(() => {
  // Check for any hidden inputs or required fields
  const inputs = Array.from(document.querySelectorAll('input'));
  const requiredInputs = inputs.filter(input => input.required || input.disabled === false);
  return requiredInputs.map(i => ({id: i.id, value: i.value, type: i.type, disabled: i.disabled}));
})()

